module protocol::referral;

// === Imports ===

use sui::table::{Self, Table};
use sui::vec_map::{ Self, VecMap };
use sui::balance::{ Balance } ;
use sui::bag::{ Self, Bag };
use sui::coin::Coin;
use sui::random::{Self, Random};

use std::string::{ Self, String };
use std::type_name::{ Self, TypeName };

use protocol::error;
use std::option::some;
use std::option::none;
use sui::event::emit;

// === Constants ===
const DENOMINATOR: u64 = 10000;
const REFERRAL_CODE_LENGTH: u64 = 6;

public struct ReferralRecordedEvent has copy, drop {
    coin_type: TypeName,
    amount: u64,
    referee: address,
    referer: address,
}

// === Structs ===
public struct Referral has key, store {
    id: UID,

    is_claim_paused: bool,

    code_owner: Table<String, address>,
    referrer_code: Table<address, String>,

    // the binding between referee to the referral code, this code once binded will not change and will
    // always be used
    referee_to_code: Table<address, String>,

    referrer_discount_bps: u64,
    referee_discount_bps: u64,
    referrer_deposit_usd_threshold: u64,

    // only allow referral code generation if deposit usd is more than `referrer_deposit_usd_threshold`
    accumulated_deposit_only_usd: Table<address, u64>,

    // flash loan coin type to rebate amount
    user_rebates_records: Table<address, VecMap<TypeName, u64>>,
    rebates: Bag,
}

// === Public Functions ===
public(package) fun has_referral_code(self: &Referral, who: address): bool { self.referrer_code.contains(who) }

public(package) fun get_referral_code(
    self: &Referral,
    who: address
): String {
    assert!(self.has_referral_code(who), error::referral_no_referral_code());
    *self.referrer_code.borrow(who)
}

public(package) fun list_rebates(self: &Referral, who: address): (vector<TypeName>, vector<u64>) { 
    let mut coin_types = vector::empty<TypeName>();
    let mut amounts = vector::empty<u64>();

    // if user has no rebate records, return empty vectors
    if (!self.user_rebates_records.contains(who)) {
        return (coin_types, amounts)
    };

    let user_rebates = self.user_rebates_records.borrow(who);
    user_rebates.keys().do!(| key | {
        let amount = *user_rebates.get(&key);
        coin_types.push_back(key);
        amounts.push_back(amount);

